const listVisitorInviteHistory = `-- name: ListVisitorInviteHistory :many
SELECT
    vi.id,
    vi.society_id,
    vi.flat_id,
    vi.created_by,
    vi.purpose,
    vi.status,
    vi.expires_at,
    vi.used_at,
    vi.metadata,
    vi.created_at,
    vi.updated_at,
    sl.short_code,
    sl.expires_at AS short_link_expires_at,
    ve.id AS entry_id,
    ve.status AS entry_status,
    ve.checked_in_at,
    ve.checked_out_at,
    ve.qr_expires_at,
    ve.qr_used_at,
    v.full_name AS visitor_full_name,
    v.phone_number AS visitor_phone_number,
    v.email AS visitor_email,
    v.photo_url AS visitor_photo_url
FROM visitor_invites vi
LEFT JOIN short_links sl
    ON sl.resource_type = 'visitor_invite'
   AND sl.resource_id = vi.id
   AND sl.revoked_at IS NULL
LEFT JOIN visitor_entries ve
    ON ve.invite_id = vi.id
LEFT JOIN visitors v
    ON v.id = ve.visitor_id
WHERE vi.society_id = $1
  AND vi.flat_id = $2
  AND ($5::visitor_invite_status IS NULL OR vi.status = $5::visitor_invite_status)
  AND (
    $6::text IS NULL
    OR vi.purpose::text ILIKE '%' || $6::text || '%'
    OR vi.status::text ILIKE '%' || $6::text || '%'
    OR v.full_name ILIKE '%' || $6::text || '%'
    OR v.phone_number ILIKE '%' || $6::text || '%'
    OR v.email ILIKE '%' || $6::text || '%'
    OR sl.short_code ILIKE '%' || $6::text || '%'
  )
ORDER BY vi.created_at DESC
LIMIT $3 OFFSET $4
`

